const MODULES = [{id:'weapons',name:'Armas de plasma',icon:'⚔',max:3,base:180,description:'+5 daño de asalto / nivel'},{id:'shields',name:'Blindaje adaptativo',icon:'⬡',max:3,base:160,description:'Reduce el daño del casco'},{id:'reactor',name:'Reactor de fase',icon:'ϟ',max:3,base:200,description:'+1 energía máxima / nivel'}];
