const ACHIEVEMENTS=[{id:'expansion',name:'Primeras fronteras',description:'Conquista 3 mundos.',goal:3,reward:100,xp:30,value:()=>PLANETS.filter(p=>p.id!=='earth'&&state.worlds[p.id].owner==='player').length},{id:'solar',name:'Soberanía solar',description:'Conquista los 8 mundos hostiles.',goal:8,reward:350,xp:100,value:()=>PLANETS.filter(p=>p.id!=='earth'&&state.worlds[p.id].owner==='player').length},{id:'commander',name:'Mando experimentado',description:'Alcanza el nivel 5 de comandante.',goal:5,reward:180,xp:45,value:()=>state.level},{id:'flagship',name:'Nave insignia',description:'Mejora la flota al nivel 3.',goal:3,reward:180,xp:45,value:()=>state.shipLevel},{id:'arsenal',name:'Arsenal orbital',description:'Instala 3 niveles totales de módulos.',goal:3,reward:150,xp:40,value:()=>Object.values(state.modules).reduce((a,b)=>a+b,0)},{id:'colonizer',name:'Mundos habitados',description:'Construye 3 instalaciones coloniales.',goal:3,reward:170,xp:45,value:()=>Object.values(state.colonies).reduce((n,c)=>n+Object.values(c).reduce((a,b)=>a+b,0),0)},{id:'influence',name:'Voz de las estrellas',description:'Acumula 50 de influencia.',goal:50,reward:140,xp:35,value:()=>state.influence}];
const TACTICAL_ORDERS=[{id:'scout',title:'Cartografiar la frontera',description:'Reconoce 2 mundos distintos este ciclo.',goal:2,reward:85,xp:20},{id:'operations',title:'Golpe coordinado',description:'Ejecuta 3 operaciones de combate este ciclo.',goal:3,reward:100,xp:25},{id:'influence',title:'Red de influencia',description:'Consigue 15 de influencia este ciclo.',goal:15,reward:110,xp:25},{id:'capture',title:'Expansión inmediata',description:'Conquista 1 mundo este ciclo.',goal:1,reward:140,xp:35}];
function tacticalOrder(cycle){return TACTICAL_ORDERS[(Math.max(1,cycle)-1)%TACTICAL_ORDERS.length];}
const initialState = () => ({commander:'Comandante',level:1,xp:0,credits:420,influence:0,corruption:0,cycle:1,energy:8,maxEnergy:8,baseMaxEnergy:8,shipLevel:1,hull:100,modules:{weapons:0,shields:0,reactor:0},selected:'mercury',won:false,contractProgress:{scout:0,capture:0,influence:0},contractClaims:[],orderCycle:1,orderProgress:{scout:0,operations:0,influence:0,capture:0,scouted:[]},orderCompleted:false,colonies:{},colonyFocus:'economy',achievementsClaimed:[],achievementsRewarded:[],scoutedPlanets:[],worlds:Object.fromEntries(PLANETS.map(p=>[p.id,{defense:p.defense,owner:p.id==='earth'?'player':'enemy',scouted:false}])),log:[]});
function loadState(){try{const raw=localStorage.getItem(SAVE_KEY)||localStorage.getItem('sin-seduction-campaign-v2')||localStorage.getItem('sin-seduction-solar-campaign-v2')||localStorage.getItem('sin-seduction-solar-campaign-v1');if(!raw)return initialState();const saved=JSON.parse(raw),s={...initialState(),...saved,worlds:{...initialState().worlds,...(saved.worlds||{})},log:Array.isArray(saved.log)?saved.log.slice(0,14):[]};for(const p of PLANETS){const w=s.worlds[p.id];if(!w||typeof w!=='object')s.worlds[p.id]={defense:p.defense,owner:p.id==='earth'?'player':'enemy',scouted:false};else{w.defense=Math.max(0,Math.min(p.defense,Number.isFinite(w.defense)?w.defense:p.defense));if(!['player','enemy'].includes(w.owner))w.owner=p.id==='earth'?'player':'enemy';w.scouted=!!w.scouted;}}s.xp=Math.max(0,Number(s.xp)||0);s.level=Math.floor(s.xp/100)+1;s.maxEnergy=Math.max(8,Math.min(12,Number(s.maxEnergy)||8));s.baseMaxEnergy=Math.max(8,Math.min(12,Number(s.baseMaxEnergy)||(s.maxEnergy-(Number(s.modules?.reactor)||0))));s.shipLevel=Math.max(1,Math.min(6,Number(s.shipLevel)||1));s.modules={...initialState().modules,...(s.modules||{})};for(const m of MODULES)s.modules[m.id]=Math.max(0,Math.min(m.max,Number(s.modules[m.id])||0));s.maxEnergy=Math.min(12,s.baseMaxEnergy+s.modules.reactor);s.energy=Math.max(0,Math.min(s.maxEnergy,Number(s.energy)||0));s.energy=Math.min(s.maxEnergy,s.energy);s.credits=Math.max(0,Number(s.credits)||0);s.influence=Math.max(0,Number(s.influence)||0);s.corruption=Math.max(0,Math.min(100,Number(s.corruption)||0));if(!s.worlds[s.selected])s.selected='mercury';s.hull=Math.max(0,Math.min(100,Number.isFinite(s.hull)?s.hull:100));s.contractProgress={...initialState().contractProgress,...(s.contractProgress||{})};s.contractClaims=Array.isArray(s.contractClaims)?s.contractClaims:[];s.scoutedPlanets=Array.isArray(s.scoutedPlanets)?s.scoutedPlanets:PLANETS.filter(p=>s.worlds[p.id].scouted).map(p=>p.id);s.contractProgress.scout=s.scoutedPlanets.length;s.contractProgress.capture=Math.max(Number(s.contractProgress.capture)||0,PLANETS.filter(p=>p.id!=='earth'&&s.worlds[p.id].owner==='player').length);s.contractProgress.influence=Number(s.contractProgress.influence)||s.influence;s.orderCycle=Math.max(1,Number(s.orderCycle)||s.cycle);s.orderProgress={scout:0,operations:0,influence:0,capture:0,scouted:[],...(s.orderProgress||{})};s.orderProgress.scouted=Array.isArray(s.orderProgress.scouted)?s.orderProgress.scouted:[];s.orderCompleted=!!s.orderCompleted;s.colonies=s.colonies&&typeof s.colonies==='object'?s.colonies:{};for(const p of PLANETS){const colony=s.colonies[p.id];if(s.worlds[p.id].owner!=='player'||p.id==='earth'){delete s.colonies[p.id];continue;}if(colony&&typeof colony==='object')for(const b of COLONY_BUILDINGS)colony[b.id]=Math.max(0,Math.min(3,Number(colony[b.id])||0));}s.colonyFocus=COLONY_BUILDINGS.some(b=>b.id===s.colonyFocus)?s.colonyFocus:'economy';s.achievementsClaimed=Array.isArray(s.achievementsClaimed)?s.achievementsClaimed.filter(id=>ACHIEVEMENTS.some(a=>a.id===id)):[];s.achievementsRewarded=Array.isArray(s.achievementsRewarded)?s.achievementsRewarded.filter(id=>ACHIEVEMENTS.some(a=>a.id===id)):[];if(s.orderCycle!==s.cycle){s.orderCycle=s.cycle;s.orderProgress={scout:0,operations:0,influence:0,capture:0,scouted:[]};s.orderCompleted=false;}s.won=PLANETS.every(p=>s.worlds[p.id].owner==='player');return s;}catch{return initialState();}}
let state=loadState(),toastTimer,audio=null,soundOn=false,simPaused=false,simSpeed=1,shipTravel=null;
function save(){try{localStorage.setItem(SAVE_KEY,JSON.stringify(state));$('campaign-status').textContent='Guardado localmente';}catch{$('campaign-status').textContent='No se pudo guardar';}}
function safe(text){return String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function toast(text){const el=$('toast');el.textContent=text;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),2400);}
function countOwned(){return Object.values(state.worlds).filter(w=>w.owner==='player').length;}
function rank(level){return ['Recluta','Operador','Agente','Infiltrador','Comandante','Soberano'][Math.min(5,Math.floor((level-1)/2))];}
function available(p){return !p.requires||state.worlds[p.requires]?.owner==='player';}
function status(p){const w=state.worlds[p.id];if(p.id==='earth')return['BASE','home'];if(w.owner==='player')return['CONTROLADO','secured'];if(!available(p))return['BLOQUEADO','locked'];return w.scouted?['EXPLORADO','hostile']:['OPERABLE','open'];}
function saveLog(message,type=''){state.log.unshift({time:new Date().toLocaleTimeString('es-MX',{hour:'2-digit',minute:'2-digit'}),message,type});state.log=state.log.slice(0,14);save();renderLog();}
function updateContracts(){state.contractProgress.capture=Math.max(Number(state.contractProgress.capture)||0,PLANETS.filter(p=>p.id!=='earth'&&state.worlds[p.id].owner==='player').length);state.contractProgress.influence=Math.max(Number(state.contractProgress.influence)||0,state.influence);const before=new Set(state.contractClaims);for(const c of CONTRACTS){const progress=Math.min(c.goal,Number(state.contractProgress[c.id])||0);const complete=progress>=c.goal,claimed=before.has(c.id);if(complete&&!claimed){state.contractClaims.push(c.id);state.credits+=c.reward;saveLog(`Contrato completado: ${c.title}. Recompensa +${c.reward} créditos.`,'good');toast(`CONTRATO COMPLETADO · +${c.reward} ¢`);}}renderContracts();save();}
function renderContracts(){const box=$('contract-list');if(!box)return;box.innerHTML=CONTRACTS.map(c=>{const progress=Math.min(c.goal,Number(state.contractProgress[c.id])||0),claimed=state.contractClaims.includes(c.id),ratio=Math.round(progress/c.goal*100);return `<div class="contract ${claimed?'claimed':''}"><div class="contract-head"><b>${c.title}</b><span>${claimed?'✓ RECLAMADO':`${progress}/${c.goal}`}</span></div><small>${c.description} · +${c.reward} ¢</small><div class="contract-meter"><i style="width:${ratio}%"></i></div></div>`;}).join('');}
function renderModules(){const box=$('module-list');if(!box)return;const atBase=state.selected==='earth';$('module-location').textContent=atBase?'BASE · DISPONIBLE':'REGRESA A LA TIERRA';box.innerHTML=MODULES.map(m=>{const level=state.modules[m.id],cost=m.base*(level+1),max=level>=m.max||(m.id==='reactor'&&state.maxEnergy>=12);return `<button class="module-item" data-module="${m.id}" ${!atBase||max||state.credits<cost?'disabled':''}><span class="module-icon">${m.icon}</span><span class="module-copy"><b>${m.name} <i>NV ${level}/${m.max}</i></b><small>${m.description}</small></span><strong>${max?'MÁX.':`${cost} ¢`}</strong></button>`;}).join('');}
function renderColonies(){const p=PLANETS.find(x=>x.id===state.selected),w=state.worlds[state.selected],panel=$('colony-panel');if(!panel)return;const active=p&&p.id!=='earth'&&w.owner==='player';panel.hidden=!active;if(!active)return;const levels=state.colonies[p.id]||{economy:0,science:0,influence:0},totalLevels=Object.values(levels).reduce((a,b)=>a+b,0);$('colony-status').textContent=`${totalLevels}/6 NIVELES`;$('colony-options').innerHTML=COLONY_BUILDINGS.map(b=>{const level=levels[b.id]||0;return `<button class="colony-option ${state.colonyFocus===b.id?'selected':''}" data-building="${b.id}" ${level>=3?'disabled':''}><span class="colony-option-icon">${b.icon}</span><span><b>${b.name} · NV ${level}/3</b><small>${b.description}</small></span></button>`;}).join('');const total={economy:0,science:0,influence:0};for(const c of Object.values(state.colonies))for(const key of Object.keys(total))total[key]+=(Number(c[key])||0);$('colony-summary').textContent=`Producción por ciclo: +${total.economy*45} ¢ · +${total.science*20} XP · +${total.influence*6} influencia`;$('colony-build').disabled=totalLevels>=6||(levels[state.colonyFocus]||0)>=3||state.credits<COLONY_BUILDINGS.find(b=>b.id===state.colonyFocus).cost;$('colony-build').textContent=totalLevels>=6?'COLONIA AL MÁXIMO':(levels[state.colonyFocus]||0)>=3?'NIVEL MÁXIMO':`CONSTRUIR · ${COLONY_BUILDINGS.find(b=>b.id===state.colonyFocus).cost} ¢`;}
function buildColony(){const id=state.selected,p=PLANETS.find(x=>x.id===id),w=state.worlds[id],building=COLONY_BUILDINGS.find(b=>b.id===state.colonyFocus);if(!p||p.id==='earth'||w.owner!=='player'||!building)return;state.colonies[id]??={economy:0,science:0,influence:0};const level=state.colonies[id][building.id]||0;if(level>=3||Object.values(state.colonies[id]).reduce((a,b)=>a+b,0)>=6)return;if(state.credits<building.cost){toast(`FALTAN ${building.cost-state.credits} CRÉDITOS`);return;}state.credits-=building.cost;state.colonies[id][building.id]=level+1;saveLog(`${building.name} construida en ${p.name}, nivel ${level+1}.`,'good');toast(`${building.name.toUpperCase()} · NV ${level+1}`);save();render();}
function renderAchievements(){const box=$('achievement-list');if(!box)return;$('achievement-count').textContent=`${state.achievementsClaimed.length}/${ACHIEVEMENTS.length}`;box.innerHTML=ACHIEVEMENTS.map(a=>{const value=Math.min(a.goal,Math.max(0,Number(a.value())||0)),unlocked=value>=a.goal,claimed=state.achievementsClaimed.includes(a.id);return `<div class="achievement ${unlocked?'unlocked':''} ${claimed?'claimed':''}"><div class="achievement-main"><span class="achievement-icon">${claimed?'✓':unlocked?'✦':'◇'}</span><span class="achievement-copy"><b>${a.name}</b><small>${a.description}</small></span><span class="achievement-progress">${unlocked?'COMPLETADO':`${value}/${a.goal}`}</span></div><div class="achievement-bottom"><small>RECOMPENSA · +${a.reward} ¢ · +${a.xp} XP</small><button class="achievement-claim" data-achievement="${a.id}" ${!unlocked||claimed?'disabled':''}>${claimed?'RECLAMADO':unlocked?'RECLAMAR':'BLOQUEADO'}</button></div><div class="achievement-meter"><i style="width:${Math.round(value/a.goal*100)}%"></i></div></div>`;}).join('');}
function claimAchievement(id){const a=ACHIEVEMENTS.find(x=>x.id===id);if(!a||state.achievementsClaimed.includes(id)||a.value()<a.goal)return;state.achievementsClaimed.push(id);state.credits+=a.reward;awardXP(a.xp);saveLog(`Logro desbloqueado: ${a.name}. +${a.reward} créditos y +${a.xp} XP.`,'good');toast(`LOGRO · ${a.name.toUpperCase()} · +${a.reward} ¢`);save();render();}
function renderOrder(){const order=tacticalOrder(state.cycle),progress=state.orderProgress[order.id]||0,completed=state.orderCompleted;$('order-cycle').textContent=state.cycle;$('order-title').textContent=completed?'Orden completada · buen trabajo':order.title;$('order-description').textContent=completed?'La recompensa ya está añadida a tu campaña.':order.description;$('order-progress').textContent=`${Math.min(order.goal,progress)}/${order.goal}`;$('order-meter').style.width=`${Math.min(100,Math.round(progress/order.goal*100))}%`;$('order-status').textContent=completed?'COMPLETADA':'EN CURSO';$('order-status').classList.toggle('order-done',completed);$('order-reward').textContent=completed?'RECOMPENSA ENTREGADA':`RECOMPENSA · +${order.reward} ¢ · +${order.xp} XP`;}
function trackOrder(action,target,amount=5){if(state.orderCycle!==state.cycle){state.orderCycle=state.cycle;state.orderProgress={scout:0,operations:0,influence:0,capture:0,scouted:[]};state.orderCompleted=false;}if(state.orderCompleted)return;const order=tacticalOrder(state.cycle);if(action==='scout'){if(!state.orderProgress.scouted.includes(target)){state.orderProgress.scouted.push(target);state.orderProgress.scout=state.orderProgress.scouted.length;}}else if(action==='capture')state.orderProgress.capture++;else if(action==='influence')state.orderProgress.influence+=amount;else if(action==='combat')state.orderProgress.operations++;if((Number(state.orderProgress[order.id])||0)<order.goal)return;state.orderCompleted=true;state.credits+=order.reward;awardXP(order.xp);saveLog(`Orden táctica completada: ${order.title}. +${order.reward} créditos y +${order.xp} XP.`,'good');toast(`ORDEN COMPLETADA · +${order.reward} ¢ · +${order.xp} XP`);renderOrder();save();}
function upgradeModule(id){const m=MODULES.find(x=>x.id===id);if(!m||state.selected!=='earth')return;const level=state.modules[id];if(level>=m.max)return;const cost=m.base*(level+1);if(state.credits<cost){toast(`FALTAN ${cost-state.credits} CRÉDITOS`);return;}state.credits-=cost;state.modules[id]++;if(id==='reactor'){state.maxEnergy=Math.min(12,state.baseMaxEnergy+state.modules.reactor);state.energy=Math.min(state.maxEnergy,state.energy+1);}if(id==='shields'){state.hull=Math.min(100,state.hull+20);updateShipAppearance();}saveLog(`Hangar: ${m.name} mejorado al nivel ${state.modules[id]}.`,'good');toast(`${m.name.toUpperCase()} · NIVEL ${state.modules[id]}`);save();render();}
function awardXP(amount){const old=Math.floor(state.xp/100)+1;state.xp+=amount;state.level=Math.floor(state.xp/100)+1;if(state.level>old){const gained=state.level-old;state.baseMaxEnergy=Math.min(12,state.baseMaxEnergy+gained);state.maxEnergy=Math.min(12,state.baseMaxEnergy+state.modules.reactor);state.energy=state.maxEnergy;toast(`ASCENSO · NIVEL ${state.level} · +${gained} ENERGÍA`);saveLog(`Ascenso a nivel ${state.level}. Capacidad de flota ampliada.`,'good');}}
function render(){
 $('commander-name').textContent=state.commander;$('commander-rank').textContent=`${rank(state.level)} · Nivel ${state.level}`;$('credits-value').textContent=Math.floor(state.credits).toLocaleString('es-MX')+' ¢';$('influence-value').textContent=Math.floor(state.influence).toLocaleString('es-MX');$('corruption-value').textContent=Math.floor(state.corruption)+'%';$('cycle-value').textContent=state.cycle;$('hull-value').textContent=`${Math.floor(state.hull??100)}%`;$('hull-meter').style.width=`${Math.floor(state.hull??100)}%`;$('supply-value').textContent=state.energy<2?'REABASTECE':'OPERATIVO';$('cycle-button').textContent=state.energy===0?'CERRAR CICLO ↻':'RECARGAR 3 ⚡';$('xp-label').textContent=`${state.xp%100} / 100`;$('xp-meter').style.width=`${state.xp%100}%`;$('energy-label').textContent=`${state.energy} / ${state.maxEnergy} ⚡`;$('energy-bar').innerHTML=Array.from({length:state.maxEnergy},(_,i)=>`<i class="${i>=state.energy?'empty':''}"></i>`).join('');$('world-count').textContent=`${countOwned()} / ${PLANETS.length} CONTROLADOS`;$('upgrade-cost').textContent=state.shipLevel>=6?'NIVEL MÁXIMO':`${250*state.shipLevel} ¢ · NV ${state.shipLevel}`;$('repair-button').textContent=`REPARAR · ${45+state.shipLevel*10} ¢`;$('repair-button').disabled=(state.hull??100)>=100||state.credits<45+state.shipLevel*10;$('cycle-button').disabled=state.energy>=state.maxEnergy||(state.energy<state.maxEnergy&&state.credits<55+state.maxEnergy*5);$('upgrade-button').disabled=state.won||state.shipLevel>=6||state.credits<250*state.shipLevel;
 $('world-list').innerHTML=PLANETS.map(p=>{const [text,kind]=status(p);return `<button class="world-item ${state.selected===p.id?'selected':''} ${kind==='locked'?'locked':''}" data-world="${p.id}"><span class="world-symbol" style="--world-color:#${p.color.toString(16).padStart(6,'0')}">✦</span><span class="world-copy"><b>${p.name}</b><small>${p.faction}</small></span><span class="world-status ${kind}">${text}</span></button>`;}).join('');document.querySelectorAll('.world-item').forEach(b=>b.addEventListener('click',()=>selectWorld(b.dataset.world,true)));renderTarget();renderLog();renderContracts();renderModules();renderOrder();renderColonies();renderAchievements();updateOperations();}
