const fleet=new THREE.Group(),shipMaterial=new THREE.MeshStandardMaterial({color:0xc5a0ee,metalness:.65,roughness:.28,emissive:0x351b4d,emissiveIntensity:.65}),engineGlows=[],engineFlames=[],hull=new THREE.Mesh(new THREE.ConeGeometry(.68,2.8,5),shipMaterial);hull.rotation.x=Math.PI/2;fleet.add(hull);const shieldField=new THREE.Mesh(new THREE.SphereGeometry(1.8,24,18),new THREE.MeshBasicMaterial({color:0x62dfff,transparent:true,opacity:.08,wireframe:true,depthWrite:false}));fleet.add(shieldField);const wingMaterial=new THREE.MeshStandardMaterial({color:0x7253a7,metalness:.55,roughness:.36});for(const side of[-1,1]){const wing=new THREE.Mesh(new THREE.BoxGeometry(1.65,.11,.48),wingMaterial);wing.position.set(side*.84,0,.08);fleet.add(wing);const engineGlow=new THREE.Mesh(new THREE.SphereGeometry(.24,16,12),new THREE.MeshBasicMaterial({color:0x39d9ff,transparent:true,opacity:.9,blending:THREE.AdditiveBlending,depthWrite:false}));engineGlow.position.set(side*.42,0,1.15);fleet.add(engineGlow);engineGlows.push(engineGlow);const flame=new THREE.Mesh(new THREE.ConeGeometry(.11,.92,12),new THREE.MeshBasicMaterial({color:0x59caff,transparent:true,opacity:.78,blending:THREE.AdditiveBlending,depthWrite:false}));flame.rotation.x=Math.PI/2;flame.position.set(side*.42,0,1.67);fleet.add(flame);engineFlames.push(flame);}worldGroup.add(fleet);const fleetOrbitPts=Array.from({length:80},(_,i)=>{const a=i/80*Math.PI*2;return new THREE.Vector3(Math.cos(a)*19,0,Math.sin(a)*19);});worldGroup.add(new THREE.LineLoop(new THREE.BufferGeometry().setFromPoints(fleetOrbitPts),new THREE.LineBasicMaterial({color:0x65d8e9,transparent:true,opacity:.4})));
