const effects=[];function animateAttack(id,type){const target=planetObjects.get(id);if(!target)return;const from=fleet.getWorldPosition(new THREE.Vector3()),to=target.mesh.getWorldPosition(new THREE.Vector3());shipTravel={from,to,start:performance.now(),duration:1050};const color=type==='corrupt'?0xb65bfa:type==='sabotage'?0x63e4cd:0xff596f,beam=new THREE.Line(new THREE.BufferGeometry().setFromPoints([from,to]),new THREE.LineBasicMaterial({color,transparent:true,opacity:.95}));scene.add(beam);const pulse=new THREE.Mesh(new THREE.SphereGeometry(target.data.size*1.4,18,14),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.34,wireframe:true}));target.mesh.add(pulse);effects.push({beam,pulse,end:performance.now()+950});}
