for(const[id,action]of[['op-scout','scout'],['op-infiltrate','infiltrate'],['op-assault','assault'],['op-corrupt','corrupt']])$(id).dataset.op=action;$('operation-buttons').addEventListener('click',event=>{const button=event.target.closest('button[data-op]');if(button&&!button.disabled)operation(button.dataset.op);});$('cycle-button').addEventListener('click',nextCycle);$('repair-button').addEventListener('click',repairShip);$('upgrade-button').addEventListener('click',upgrade);$('module-list').addEventListener('click',event=>{const button=event.target.closest('button[data-module]');if(button&&!button.disabled)upgradeModule(button.dataset.module);});$('colony-options').addEventListener('click',event=>{const button=event.target.closest('button[data-building]');if(!button||button.disabled)return;state.colonyFocus=button.dataset.building;renderColonies();});$('colony-build').addEventListener('click',buildColony);$('achievement-list').addEventListener('click',event=>{const button=event.target.closest('button[data-achievement]');if(button&&!button.disabled)claimAchievement(button.dataset.achievement);});$('save-button').addEventListener('click',()=>{save();toast('Campaña guardada en este navegador.');});$('rename-button').addEventListener('click',()=>{const value=prompt('Nombre del comandante (máximo 24 caracteres):',state.commander);if(value===null)return;const name=value.trim().slice(0,24);if(name){state.commander=name;save();render();toast('Identidad actualizada.');}});$('reset-button').addEventListener('click',async()=>{if(!await confirmDialog({title:'Reiniciar campaña',text:'Se borrará tu progreso de este navegador.',confirm:'REINICIAR',danger:true}))return;state=initialState();localStorage.removeItem('sin-seduction-campaign-v2');localStorage.removeItem('sin-seduction-solar-campaign-v2');localStorage.removeItem('sin-seduction-solar-campaign-v1');save();render();selectWorld('mercury',true);saveLog('Nueva campaña iniciada. Reconoce Mercurio para iniciar.');});$('sound-toggle').addEventListener('click',()=>{soundOn=!soundOn;if(soundOn){audio??=new AudioContext();audio.resume();playTone(520,.12,'triangle');}$('sound-toggle').classList.toggle('active',soundOn);toast(soundOn?'Efectos de sonido activados.':'Efectos de sonido desactivados.');});
$('orbit-pause').addEventListener('click',()=>{simPaused=!simPaused;$('orbit-pause').textContent=simPaused?'▶ SEGUIR':'Ⅱ PAUSA';saveOrbit();});$('orbit-speed').addEventListener('input',e=>{simSpeed=Number(e.target.value);$('orbit-speed-value').textContent=simSpeed.toFixed(1)+'×';saveOrbit();});$('orbit-trails').addEventListener('change',e=>{orbits.forEach(x=>x.visible=e.target.checked);saveOrbit();});function saveOrbit(){localStorage.setItem('sin-seduction-orbit-options',JSON.stringify({paused:simPaused,speed:simSpeed,trails:$('orbit-trails').checked}));}try{const options=JSON.parse(localStorage.getItem('sin-seduction-orbit-options'));if(options){simPaused=!!options.paused;simSpeed=Math.max(0,Math.min(3,Number.isFinite(Number(options.speed))?Number(options.speed):1));$('orbit-speed').value=simSpeed;$('orbit-speed-value').textContent=simSpeed.toFixed(1)+'×';$('orbit-pause').textContent=simPaused?'▶ SEGUIR':'Ⅱ PAUSA';$('orbit-trails').checked=options.trails!==false;orbits.forEach(x=>x.visible=$('orbit-trails').checked);}}catch{}
async function refreshServer(){try{const r=await fetch('/api/world',{headers:{Accept:'application/json'}});if(!r.ok)throw Error();const data=await r.json();$('campaign-status').textContent=`Ktor en línea · ${data.playerCount} jugador(es)`;}catch{$('campaign-status').textContent='Campaña local · guardada en navegador';}}refreshServer();setInterval(refreshServer,15000);window.addEventListener('pagehide',save);window.addEventListener('storage',event=>{if(event.key===SAVE_KEY&&event.newValue){state=loadState();render();}});document.addEventListener('visibilitychange',()=>{if(document.hidden)save();});window.addEventListener('error',e=>{console.error(e.error||e.message);$('campaign-status').textContent='Error de ejecución';});render();updateShipAppearance();if(!state.log.length)saveLog('Campaña iniciada. Reconoce Mercurio para revelar sus defensas.');selectWorld(state.selected,true);if(state.won&&!localStorage.getItem('sin-seduction-victory-seen-v1')){localStorage.setItem('sin-seduction-victory-seen-v1','1');setTimeout(showVictory,700);}
